ACTIVATION_X_MIN = 5.0
AGENT_MASS = 5.0
BACKWARD_FX_THRESHOLD = -34.0
BACKWARD_SPEED_MAX = 100.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0
WALL_AVOIDANCE_THRESHOLD = 0.3  # Avoid floor contact
MAX_FORWARD_FORCE = 150.0  # Increased to overcome damping and shear
MIN_FORWARD_FORCE = 20.0
VERTICAL_ADJUSTMENT_GAIN = 100.0  # Stronger vertical control
DAMPING_ADJUSTMENT_GAIN = 20.0
FLOOR_Y = 1.0  # Target y above floor to avoid shear
SAFE_Y = 1.2  # Target y to avoid floor shear

def _control_cfg(_sandbox):
    return {
        "act_lo": ACTIVATION_X_MIN,
        "act_hi": ACTIVATION_X_MAX,
        "bfx": BACKWARD_FX_THRESHOLD,
        "bspd": BACKWARD_SPEED_MAX,
    }

class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}

MEM = Memory()

def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(AGENT_MASS) * abs(gy)

def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
        }
    state = MEM.data["initial_state"]
    cfg = _control_cfg(sandbox)
    pd = sandbox.get_agent_position()
    dt = TIME_STEP
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = SAFE_Y, _weight_comp(sandbox)  # Target y to avoid floor shear
    front, up, down = sandbox.get_whisker_readings()

    # Phase 1: APPROACH - Ensure floor contact and move forward
    if state["phase"] == "APPROACH":
        # Apply forward force when not too close to floor
        if down > WALL_AVOIDANCE_THRESHOLD:
            fx = MAX_FORWARD_FORCE
            fy = VERTICAL_ADJUSTMENT_GAIN * (ty - y) - DAMPING_ADJUSTMENT_GAIN * vyd + w_comp
        else:
            # Apply strong upward force to avoid floor
            fy = -VERTICAL_ADJUSTMENT_GAIN * (y - ty) - DAMPING_ADJUSTMENT_GAIN * vyd
            fx = MAX_FORWARD_FORCE * 0.5  # Reduce forward force when near floor

        # Transition to UNLOCK phase when in activation zone
        if cfg["act_lo"] <= x <= cfg["act_hi"]:
            state["phase"] = "UNLOCK"
            state["t"] = 0
    elif state["phase"] == "UNLOCK":
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        # Apply backward force strictly less than -34.0 N
        fx_cmd = -35.0
        fy_cmd = VERTICAL_ADJUSTMENT_GAIN * (ty - y) - DAMPING_ADJUSTMENT_GAIN * vyd + w_comp  # Maintain y-position
        # Apply correction to stabilize if moving too fast
        if spd >= cfg["bspd"] * 0.99:
            horiz = -1.5 * vx_p
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * vy_p
        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        # Transition to ESCAPE phase after 60 steps in UNLOCK
        if state["t"] > 60:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Apply forward force to reach exit zone
        fx, fy = MAX_FORWARD_FORCE, VERTICAL_ADJUSTMENT_GAIN * (ty - y) - DAMPING_ADJUSTMENT_GAIN * vyd + w_comp
        # Transition to HOLD phase when in exit zone
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Minimal force to maintain position in exit zone
        fx, fy = 0.0, w_comp

    sandbox.apply_agent_force(fx, fy)

